insert into public.menu_items (item_key,type,section_id,section_title,name,description,volume,price,image_url,available,sort_order,archived,badge) values
('bar:napitki:coca-cola','bar','napitki','Напитки','Coca-Cola','Coca-Cola – один из самых популярных безалкогольных напитков в истории, а также один из наиболее узнаваемых брендов в мире.','',400,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-vdsiob-uwa-mhgrmxshtn-bJyfNUtvqeanSd3ykb-9W.jpg',true,0,false,''),
('bar:napitki:coca-cola-zero','bar','napitki','Напитки','Coca-Cola zero','Coca-Cola Zero – это возможность насладиться удивительно освежающим вкусом классической Coca-Cola, не задумываясь о калориях. Coca-Cola Zero - отличный вкус без сахара и калорий!','',400,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-vdsiob-uwa-uc-cornwht-OKO5lDffPoFEhK73rTOZ3.jpg',true,1,false,''),
('bar:napitki:fanta','bar','napitki','Напитки','Fanta','Fanta Апельсин – это классический безалкогольный напиток с легким фруктовым вкусом, содержащий 3% натурального апельсинового сока.','',400,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-vdsiob-uwa-knhsikzxju-fSIc0mh-939Lnpz3RbCXW.jpg',true,2,false,''),
('bar:napitki:пепси','bar','napitki','Напитки','Пепси','','',380,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-jutf-vdsiob-uwa-nhilflevqs-yL6gEop8XHlz76DJXNmz5.jpg',true,3,false,''),
('bar:napitki:тоник','bar','napitki','Напитки','Тоник','','',350,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-jutf-vdsiob-uwa-jakzoubtaz-beigUqQYjzRt8GyRAHMgB.jpg',true,4,false,''),
('bar:napitki:dr-pepper','bar','napitki','Напитки','Dr Pepper','Освежающий безалкогольный сильногазированный пастеризованный напиток Dr Pepper Regular (Classic). Dr Pepper Classic представляет собой уникальное сочетание 23 различных оттенков вкуса (амаретто, миндаль, ежевика, чёрная солодка, морковь, гвоздика, вишня, карамель, кола, имбирь, можжевельник, лимон, патока, мускатный орех, апельсин, чернослив, слива, перец, ром, малина, помидоры, ваниль и секретный ингредиент производителя).','',400,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-vdsiob-uwa-hdtpod-xyw-tjRIUeCk4C0IZAf9J018H.jpg',true,5,false,''),
('bar:napitki:red-bull','bar','napitki','Напитки','Red bull','Red Bull Energy Drink — безалкогольный энергетический газированный напиток. Энергетические напитки Red Bull содержат ингредиенты высокого качества: кофеин, таурин, витамины B, сахар и воду из альпийских регионов. В одной банке 250 мл содержится столько же кофеина, сколько в чашке кофе такого же объема.','',500,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-vdsiob-uwa-ctxycxeiaj-4Mz_7j5QlRt64zQn691M0.jpg',true,6,false,''),
('bar:napitki:red-bull-sugarfree','bar','napitki','Напитки','Red bull sugarfree','Red Bull Sugarfree — безалкогольный тонизирующий газированный напиток без сахара.','',500,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-vdsiob-uwa-rmyicokztj-OWNv_h-PyiQFiOyAB50Ff.jpg',true,7,false,''),
('bar:napitki:соки-swell','bar','napitki','Напитки','Соки Swell','Swell (Свелл) — это высококачественные соки и нектары, изготовленные по новейшим технологиям на современном европейском оборудовании, которое позволяет сохранять витамины и полезные вещества в готовом продукте.','',350,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-vdsiob-uwa-a-vevanmfa-jBdOIzVKItzZMAI6cw_fp.jpg',true,8,false,''),
('bar:napitki:вода-без-газа','bar','napitki','Напитки','Вода без газа','Природная минеральная столовая вода обладает сбалансированным вкусом. Уникальный полноценный состав воды включает в себя микроэлементы и минералы, необходимые для поддержки здоровья. Вода Mever рекомендована для ежедневного употребления.','',350,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-vdsiob-uwa-jhdqwoslzx-svyk1JJot-c7vAqgA6N6T.jpg',true,9,false,''),
('bar:napitki:вода-с-газом','bar','napitki','Напитки','Вода с газом','Borjomi — легендарная вода, которой больше 130 лет, ее знают и любят миллионы людей по всему миру. Она зарождается в вулканических глубинах Грузии в экологически чистой долине «Боржоми» и благодаря сочетанию полезных свойств вулканической воды и заряжающей силой минералов и микроэлементов Borjomi заботится о вашем здоровье, а узнаваемый с первого глотка вкус придает силы на новые свершения и идеи!','',500,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-vdsiob-uwa-j-nojqhwzw-Tx5f2JS0F25H9fiP4r18e.jpg',true,10,false,''),
('bar:napitki:авторские-лимонады-ананас-лемонграсс-манго-маракуйя-ежевика-гранат-слива-рислинг-фейхоа-иланг-иланг','bar','napitki','Напитки','Авторские лимонады (Ананас-лемонграсс; манго-маракуйя; ежевика-гранат; слива-рислинг; фейхоа-иланг-иланг)','Лимонад - один из любимейших прохладительных напитков, вкус которого мы узнаём с детства.','',1000,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-vdsiob-uwa-vsncndtncz-eHIjiV0Y3LX2vA7jUje_Q.jpg',true,11,false,''),
('bar:napitki:авторские-лимонады-0-4-ананас-лемонграсс-манго-маракуйя-ежевика-гранат-слива-рислинг-фейхоа-иланг-иланг','bar','napitki','Напитки','Авторские лимонады 0,4 (Ананас-лемонграсс; манго-маракуйя; ежевика-гранат; слива-рислинг; фейхоа-иланг-иланг)','','',550,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-vdsiob-uwa-wtzk-rcgnz-aX1-ba97GEwmo4X_5H9Mc.jpg',true,12,false,''),
('bar:napitki:холодный-чай','bar','napitki','Напитки','Холодный чай','','',1000,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-jutf-vdsiob-uwa-rfihnvouxv-Rn08_IyuAm4SggBH4xSBy.jpg',true,13,false,''),
('bar:chaynaya-karta:молочный-улун-900мл','bar','chaynaya-karta','Чайная карта','Молочный улун 900мл','Молочный улун – один из самых популярных сортов улуна в мире. Его любят за яркий и легкий сливочный вкус, тонизирующий эффект и полезные для организма свойства','',800,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-tpzfbqwhfe-mxdn-vuuaq-X-1RMueEpHiRZBXsZBvVV.jpg',true,14,false,''),
('bar:chaynaya-karta:манговый-улун-900мл','bar','chaynaya-karta','Чайная карта','Манговый улун 900мл','','',800,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-jutf-tpzfbqwhfe-mth-upiiun-NOBlhvKTNN0thVTUtDRFy.jpg',true,15,false,''),
('bar:chaynaya-karta:жасминовый-900мл','bar','chaynaya-karta','Чайная карта','Жасминовый 900мл','','',800,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-jutf-tpzfbqwhfe-qhxdvnvlpd-a_yETTaKKjugARe1SGSlg.jpg',true,16,false,''),
('bar:chaynaya-karta:сенча-900мл','bar','chaynaya-karta','Чайная карта','Сенча 900мл','Сенча – классический китайский зеленый чай, обладающий сладковатым, чуть вяжущим вкусом и нежным свежим ароматом.','',800,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-tpzfbqwhfe-jheaatvkov-DH64DGY14IrApwySAKbE0.jpg',true,17,false,''),
('bar:chaynaya-karta:ассам-900мл','bar','chaynaya-karta','Чайная карта','Ассам 900мл','Ассам богат антиоксидантами, замедляющими процессы старения и предотвращающими развитие хронических заболеваний сердечно-сосудистой системы.','',800,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-tpzfbqwhfe-kxeivklqqe-8rlACWGrgroaOaLeoBeac.jpg',true,18,false,''),
('bar:chaynaya-karta:эрл-грей-900мл','bar','chaynaya-karta','Чайная карта','Эрл Грей 900мл','','',800,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-jutf-tpzfbqwhfe-ncrrjydjuv-RaZVXFN1bIwT1CInNfl3Q.jpg',true,19,false,''),
('bar:chaynaya-karta:наглый-фрукт-900мл','bar','chaynaya-karta','Чайная карта','Наглый фрукт 900мл','Насыщенный дерзкий вкус, ярко-фруктовый, кисловатый, с горчинкой.','',800,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-tpzfbqwhfe-n-bkxhcj-x-VPXunavCFrPd2dGkqpqPq.jpg',true,20,false,''),
('bar:chaynaya-karta:здоровый-сон-490мл','bar','chaynaya-karta','Чайная карта','Здоровый сон 490мл','Напиток чайный Здоровый сон – вкусный и полезный напиток, который поможет вам расслабиться, забыть о насущных проблемах и подготовиться ко сну.','',800,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-tpzfbqwhfe-zzweqbyzsh-rGhCGciZfrUUapkT-SoGE.jpg',true,21,false,''),
('bar:chaynaya-karta:пуэр-900мл','bar','chaynaya-karta','Чайная карта','Пуэр 900мл','Пуэр — уникальный постферментированный чай, выращенный в провинции Юннань, Китай.','',800,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-tpzfbqwhfe--pcotmbyjw-pEE8S1VTgenP1jE1xgcmH.jpg',true,22,false,''),
('bar:kitayskie-chai:пуэр-вишня-корица','bar','kitayskie-chai','Китайские чаи','Пуэр вишня-корица','Пуэр с добавлением ягод вишни и корицы. На первый план выходит вишневый вкус с легким послевкусием корицы.','',1100,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-jutf-pvziqcwwmg-jbiuwfysgf-7dxoMoOhUC9GStTIdlI35.jpg',true,23,false,''),
('bar:kitayskie-chai:шу-пуэр-гун-тин','bar','kitayskie-chai','Китайские чаи','Шу пуэр Гун Тин','Этот шу пуэр из уезда Мэнхай изготовлен из кустового сырья 2017 года, что наделило его зрелым и сбалансированным характером. Его аромат сдержанный и тёплый, с пряными и ореховыми нотами. Во вкусе мягкая ореховая основа гармонично переплетается с лёгкими оттенками сушёных ягод, а финал оставляет приятное, бархатисто-сладковатое послевкусие.','',1100,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-jutf-pvziqcwwmg-z-mjqcqqjo-xJayrGllPHNSvHqJTGe0X.jpg',true,24,false,''),
('bar:kitayskie-chai:бай-хао-инь-чжень','bar','kitayskie-chai','Китайские чаи','Бай Хао Инь Чжень','Данный белый чай, как и прочие белые чаи, не подвергается никакой обработке. Его аккуратно собирают вручную, не скручивают, не подвергают ферментации, а просто слегка подсушивают при помощи солнечных лучей. Можно сказать, что белый чай Бай Хао Инь Чжэнь – природный продукт, в котором сохраняется вся польза, все витамины и микроэлементы. Считается, что Бай Хао Инь Чжэнь – напиток, который помогает поддерживать здоровье и красоту.','',1100,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-jutf-pvziqcwwmg-exkjoskdzj-sPIgVK6oT6jgolewd3Pbg.jpg',true,25,false,''),
('bar:kitayskie-chai:бай-му-дань','bar','kitayskie-chai','Китайские чаи','Бай Му Дань','Китайский белый чай уезда Фудин, провинции Фуцзянь. Его начали производить с 1960-х годов, в настоящее время его делают, в основном, в уезде Чжэньхэ, Цзяньян, Фудин и Сунси. Чайный лист Бай Му Дань очень похож на листья пиона, благодаря чему заслужил свое название «Белый пион».','',1100,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-jutf-pvziqcwwmg-jjvfsxeedo-tyb3gsrumFRcWvs_0AkOD.jpg',true,26,false,''),
('bar:kitayskie-chai:ганпаудер','bar','kitayskie-chai','Китайские чаи','Ганпаудер','Ганпаудер — знаменитый китайский чай, который в Китае называют Люй Чжу, то есть «зелёная жемчужина». Чайный лист скручивают в маленькие шарики, которые становятся похожими на порох. Из-за внешнего вида этот чай также называют gunpowder, что с английского переводится как «порох».','',1100,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-jutf-pvziqcwwmg-mbylx--dtk-UwPm7EkqdLnATQdWI9Iwe.jpg',true,27,false,''),
('bar:kitayskie-chai:мао-фен','bar','kitayskie-chai','Китайские чаи','Мао Фен','Не только название скрутки листа, но и способ производства чая, при котором отбираются почки и прилегающие к ним два листа одинаковой длины. Такой чай отличается сбалансированным и богатым вкусом.','',1100,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-jutf-pvziqcwwmg-dnjmie-zur-Jb5VD0NoBSojlE5R3zNmc.jpg',true,28,false,''),
('bar:kitayskie-chai:те-гуань-инь','bar','kitayskie-chai','Китайские чаи','Те Гуань Инь','Вкус этого чая свежий, с легкой сладостью и характерным для улунов привкусом талого снега. Чайный напиток обладает ярким цветочным ароматом с нотами спелых яблок. Цвет настоя светло-желтый, прозрачный, который при последующих завариваниях становится зеленоватым.','',1100,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-jutf-pvziqcwwmg-njqm-s-oy--RKEbfmWfWFIoTQJGwUGvB.jpg',true,29,false,''),
('bar:kitayskie-chai:да-хун-пао','bar','kitayskie-chai','Китайские чаи','Да Хун Пао','Вкусовые свойства Да Хун Пао будут отличаться с каждым последующим чаепитием. Это многогранный чай, который с каждым проливом раскрывается по-новому. Многим кажется, что во время чаепития с Да Хун Пао, они успевают попробовать сразу несколько сортов чая. У него мягкое и бархатистое послевкусие, а еще легкая терпкость, которая со временем становится сладко-фруктовой.','',1100,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-jutf-pvziqcwwmg--v-gzkg--e-NriLH2Kr3bXSYM6-vQMXW.jpg',true,30,false,''),
('bar:kitayskie-chai:габа-фермерская','bar','kitayskie-chai','Китайские чаи','Габа Фермерская','Уникальный чай с тайваньских фермерских чайных садов. Отличается особенным, своеобразным вкусом и ярким цветочным ароматом. Чай Габа Фермерская легко пьется и порадует ценителей мягким, при этом насыщенным вкусом с тонкими хлебными, сладковатыми и чуть кислыми нотками.','',1100,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-jutf-pvziqcwwmg-oxgyrsjiim-MJSYWEu6OG-fkpOT4y0Rl.jpg',true,31,false,''),
('bar:dobavki-k-chayu:лимон','bar','dobavki-k-chayu','Добавки к чаю','Лимон','','',150,'https://static.foodeon.com/assets/uploaded-media/product-media/posidym-gqxz-vgejqoyhou-iybdegirxs-3sEuKlzbmw6EbBwrKEeLp.jpg',true,32,false,''),
