-- МЯТА PLATINUM СПАРТАК: актуальные данные меню для v24.
-- Порядок: schema.sql → upgrade-v22.sql → seed.sql → make-admin.sql.

on conflict (id) do update set venue_name=excluded.venue_name,address=excluded.address,phone=excluded.phone,hours=excluded.hours;

on conflict(section_id) do update set type=excluded.type,title=excluded.title,note=excluded.note,sort_order=excluded.sort_order,visible=excluded.visible;

on conflict (item_key) do update set section_id=excluded.section_id,section_title=excluded.section_title,name=excluded.name,description=excluded.description,volume=excluded.volume,price=excluded.price,image_url=excluded.image_url,available=excluded.available,sort_order=excluded.sort_order,archived=excluded.archived,badge=excluded.badge;

